-- This script will manage the static data from for UTIL.ADF_FILE_COPY_CONTROL

SELECT 'Updating static data table UTIL.ADF_FILE_COPY_CONTROL';

-- 1: Define table variable
CREATE OR REPLACE TEMPORARY TABLE UTIL.TMP_ADF_FILE_COPY_CONTROL (
	ADF_FILE_COPY_CONTROL_KEY NUMBER(38,0) NOT NULL,
    INSERT_DATETIME TIMESTAMP_TZ(9) NOT NULL,
    UPDATE_DATETIME TIMESTAMP_TZ(9) NOT NULL,
	IS_ACTIVE BOOLEAN NOT NULL,
	SOURCE_FILENAME_PATTERN VARCHAR NOT NULL,
	TARGET_DATA_LAKE_PATH VARCHAR NOT NULL,
    TARGET_SCHEMA_NAME VARCHAR ,
	TARGET_TABLE_NAME VARCHAR,
    TRUNCATE_TABLE_FLAG BOOLEAN NOT NULL,
    IS_COPY_INTO_FLAG BOOLEAN NOT NULL,
    COPY_INTO_QUERY VARCHAR,
    QUERY_FILE_FORMAT VARCHAR,
    FIXED_WIDTH VARCHAR,
    CHILD_PIPELINE VARCHAR,
	CONSTRAINT PK_ADF_FILE_COPY_CONTROL PRIMARY KEY (ADF_FILE_COPY_CONTROL_KEY),
	CONSTRAINT UK_ADF_FILE_COPY_CONTROL UNIQUE (SOURCE_FILENAME_PATTERN)
);
-- 2: Populate the table variable with data
-- This is where you manage your data in source control. You
-- can add and modify entries, but because of potential foreign
-- key contraint violations this script will not delete any
-- removed entries. If you remove an entry then it will no longer
-- be added to new databases based on your schema, but the entry
-- will not be deleted from databases in which the value already exists.
;

-- 3: Insert any new items into the table from the table variable
SELECT TMP.ADF_FILE_COPY_CONTROL_KEY, TMP.IS_ACTIVE, TMP.INSERT_DATETIME, TMP.UPDATE_DATETIME, TMP.SOURCE_FILENAME_PATTERN, TMP.TARGET_DATA_LAKE_PATH,TMP.TARGET_SCHEMA_NAME, TMP.TARGET_TABLE_NAME, TMP.TRUNCATE_TABLE_FLAG, TMP.IS_COPY_INTO_FLAG, TMP.COPY_INTO_QUERY, TMP.QUERY_FILE_FORMAT, TMP.FIXED_WIDTH, TMP.CHILD_PIPELINE
FROM UTIL.TMP_ADF_FILE_COPY_CONTROL TMP
    LEFT JOIN UTIL.ADF_FILE_COPY_CONTROL TBL ON TBL.ADF_FILE_COPY_CONTROL_KEY = TMP.ADF_FILE_COPY_CONTROL_KEY
WHERE TBL.ADF_FILE_COPY_CONTROL_KEY IS NULL
;
-- 4: Update any modified values with the values from the table variable
UPDATE UTIL.ADF_FILE_COPY_CONTROL LIVE_TABLE
SET
LIVE_TABLE.ADF_FILE_COPY_CONTROL_KEY = TMP.ADF_FILE_COPY_CONTROL_KEY,
LIVE_TABLE.IS_ACTIVE = TMP.IS_ACTIVE,
LIVE_TABLE.INSERT_DATETIME = TMP.INSERT_DATETIME,
LIVE_TABLE.UPDATE_DATETIME = TMP.UPDATE_DATETIME,
LIVE_TABLE.SOURCE_FILENAME_PATTERN = TMP.SOURCE_FILENAME_PATTERN,
LIVE_TABLE.TARGET_DATA_LAKE_PATH = TMP.TARGET_DATA_LAKE_PATH,
LIVE_TABLE.TARGET_SCHEMA_NAME = TMP.TARGET_SCHEMA_NAME,
LIVE_TABLE.TARGET_TABLE_NAME = TMP.TARGET_TABLE_NAME,
LIVE_TABLE.TRUNCATE_TABLE_FLAG = TMP.TRUNCATE_TABLE_FLAG,
LIVE_TABLE.IS_COPY_INTO_FLAG = TMP.IS_COPY_INTO_FLAG,
LIVE_TABLE.COPY_INTO_QUERY = TMP.COPY_INTO_QUERY, 
LIVE_TABLE.QUERY_FILE_FORMAT = TMP.QUERY_FILE_FORMAT,
LIVE_TABLE.FIXED_WIDTH = TMP.FIXED_WIDTH,
LIVE_TABLE.CHILD_PIPELINE = TMP.CHILD_PIPELINE
FROM UTIL.TMP_ADF_FILE_COPY_CONTROL TMP
    WHERE LIVE_TABLE.ADF_FILE_COPY_CONTROL_KEY = TMP.ADF_FILE_COPY_CONTROL_KEY
;

SELECT 'Finished updating static data table UTIL.ADF_FILE_COPY_CONTROL';